function renderAvailabilityBoard(){const board=$('#availabilityBoard'),dates=eventDates();if(!dates.length){board.innerHTML='';$('#availDates').innerHTML='';return;}if(!dates.includes(state.availDate))state.availDate=dates[0];const peopleOn=date=>[...new Set(state.availability.filter(a=>a.date===date).map(a=>a.name))];$('#availDates').innerHTML=segHtml(dates.map((date,i)=>({value:date,label:dayName(date,i),sub:shortDay(date),badge:`${peopleOn(date).length}名`})),state.availDate,'data-avail-date');const date=state.availDate,entries=state.availability.filter(a=>a.date===date),hours=hoursForDate(date),names=peopleOn(date).sort((a,b)=>a.localeCompare(b,'ja'));const can=(name,h)=>entries.some(a=>a.name===name&&a.start<=h&&a.end>=plusHour(h));board.innerHTML=`<div class="availability-wrap"><table class="availability-table"><thead><tr><th>スタッフ（${names.length}名）</th>${hours.map(h=>`<th>${h}</th>`).join('')}</tr><tr class="count-row"><th>勤務可能人数</th>${hours.map(h=>`<th>${names.filter(n=>can(n,h)).length}人</th>`).join('')}</tr></thead><tbody>${names.map(name=>`<tr><td>${esc(name)}</td>${hours.map(h=>can(name,h)?'<td class="yes">○</td>':'<td class="no">—</td>').join('')}</tr>`).join('')}</tbody></table></div>`;}
function renderMembers(){const body=$('#memberEditor');const all=[...new Set(state.availability.map(a=>a.name))].sort((a,b)=>a.localeCompare(b,'ja'));const norm=v=>v.normalize('NFKC').replace(/\s/g,''),q=norm(state.memberQuery),sf=state.memberStore,storesOf=n=>state.memberStores[n]||[];$('#memberStoreFilter').innerHTML=chipHtml([{value:'',label:'すべて',badge:all.length},...storeNames.map(s=>({value:s,label:s,cls:storeClass(s),badge:all.filter(n=>storesOf(n).includes(s)).length})),{value:'none',label:'店舗未設定',badge:all.filter(n=>!storesOf(n).length).length}],sf,'data-member-filter');const names=all.filter(n=>(!q||norm(n).includes(q))&&(!sf||(sf==='none'?!storesOf(n).length:storesOf(n).includes(sf))));$('#memberShown').textContent=names.length===all.length?`${all.length}名`:`${names.length} / ${all.length}名を表示`;body.innerHTML=names.length?names.map(name=>{const stores=storesOf(name);return `<tr class="${!state.memberStatuses[name]||!stores.length?'needs-attention':''}"><td>${esc(name)}</td><td><select data-member="${esc(name)}">${statusOptions(state.memberStatuses[name]||'未設定')}</select></td><td><div class="store-checks">${Object.keys(rolesByStore).map(store=>`<label><input type="checkbox" data-member-store="${esc(name)}" value="${store}" ${stores.includes(store)?'checked':''}>${store}</label>`).join('')}</div></td><td><div class="store-checks">${dripTypes.map(t=>`<label><input type="checkbox" data-member-drip="${esc(name)}" value="${t}" ${(state.memberDrips[name]||[]).includes(t)?'checked':''}>${t}</label>`).join('')}</div></td><td><label class="car-check"><input type="checkbox" data-member-car="${esc(name)}" ${state.memberCars[name]?'checked':''}>あり</label></td><td><input class="pref-input" data-member-want="${esc(name)}" value="${esc((state.memberWants[name]||[]).join('、'))}" placeholder="例：レジ、ホール"></td><td><input class="pref-input" data-member-dislike="${esc(name)}" value="${esc((state.memberDislikes[name]||[]).join('、'))}"></td></tr>`;}).join(''):'<tr><td colspan="7" class="no-match">該当するメンバーがいません</td></tr>';}
function renderRoleRules(){const body=$('#roleRuleEditor');const liveDates=Object.keys(eventDays).filter(d=>!eventDayRoles[d]);const groups=[...Object.entries(eventDayRoles).map(([date,roles])=>[`${eventDays[date]||date}（${shortDay(date)}）`,roles]),[`本番（${liveDates.map(shortDay).join('・')}）`,rolesByStore]];body.innerHTML=groups.map(([day,byStore])=>`<tr class="group-row"><th colspan="3">${esc(day)}</th></tr>`+Object.entries(byStore).flatMap(([store,roles])=>roles.map(([role])=>`<tr><td><span class="store-chip ${storeClass(store)}">${esc(store)}</span></td><td>${esc(role)}${carRoles.includes(role)?'<small class="rule-note">車ありのみ</small>':''}${roleStore[role]?`<small class="rule-note">${roleStore[role]}所属のみ</small>`:''}</td><td><select data-rule="${esc(ruleKey(store,role))}">${statusOptions(state.roleRequirements[ruleKey(store,role)]||'未設定',true)}</select></td></tr>`)).join('')).join('');}
function hoursForDate(date){const entries=state.availability.filter(a=>a.date===date);if(!entries.length)return [];const first=Math.min(...entries.map(a=>Number(a.start.slice(0,2))));const last=Math.max(...entries.map(a=>Number(a.end.slice(0,2))));return Array.from({length:Math.max(0,last-first)},(_,i)=>String(first+i).padStart(2,'0')+':00');}
function ensureGridSlots(date,hours){for(const hour of hours){for(const [store,roles] of Object.entries(rolesForDate(date))){for(const [role,count] of roles){if(!state.slots.some(s=>s.date===date&&s.store===store&&s.role===role&&s.start===hour)){const id=slotId(date,store,role,hour);state.slots.push({id,date,store,role,start:hour,end:plusHour(hour),count:state.slotCounts[id]??count});}}}}}
const breakRoles=['昼食','休憩'];
const toMin=t=>Number(t.slice(0,2))*60+Number(t.slice(3));
function mergeSpans(items){const spans=[];for(const x of [...items].sort((a,b)=>a.start.localeCompare(b.start))){const last=spans[spans.length-1];if(last&&toMin(x.start)<=last.end)last.end=Math.max(last.end,toMin(x.end));else spans.push({start:toMin(x.start),end:toMin(x.end)});}return spans;}
function assignmentAudit(){const assigned=flattened().filter(item=>state.assignments[item.key]).map(item=>({...item,name:state.assignments[item.key]}));const conflicts=new Set(),hours={},booked={};for(const x of assigned)(booked[`${x.name}|${x.date}`]??=[]).push(x);for(const [id,items] of Object.entries(booked)){const [name,date]=id.split('|');for(let i=0;i<items.length;i++)for(let j=i+1;j<items.length;j++)if(items[j].start<items[i].end&&items[i].start<items[j].end){conflicts.add(items[i].key);conflicts.add(items[j].key);}const spans=mergeSpans(items.filter(x=>!breakRoles.includes(x.role)));(hours[name]??={})[date]=spans.reduce((sum,sp)=>sum+sp.end-sp.start,0)/60;}return {conflicts,hours,booked};}
const fmt=h=>`${Number.isInteger(h)?h:h.toFixed(1)}h`;
function renderAudit(audit=assignmentAudit()){const box=$('#assignmentAudit'),badge=$('#auditBadge'),{conflicts,hours}=audit;badge.textContent=conflicts.size?`重複 ${conflicts.size}`:'';badge.classList.toggle('hidden',!conflicts.size);if(!state.availability.length){box.innerHTML='<div class="audit-title"><strong>勤務状況チェック</strong></div><p class="hours-note">アンケート回答CSVを読み込むと表示されます。</p>';return;}const dates=[...new Set(state.availability.map(a=>a.date))].sort().slice(0,3);const names=[...new Set(state.availability.map(a=>a.name))].sort((a,b)=>a.localeCompare(b,'ja'));const disliked=flattened().filter(x=>state.assignments[x.key]&&dislikes(state.assignments[x.key],x.role)).length;const rows=names.map(name=>{const perDay=dates.map(date=>state.availability.some(a=>a.name===name&&a.date===date)?(hours[name]?.[date]||0):null);const total=perDay.reduce((sum,h)=>sum+(h||0),0);return `<tr><td>${esc(name)}</td>${perDay.map(h=>h===null?'<td class="off">—</td>':`<td class="${h?'':'zero'}">${fmt(h)}</td>`).join('')}<td class="total">${fmt(total)}</td></tr>`;}).join('');box.innerHTML=`<div class="audit-title"><strong>勤務状況チェック</strong><div class="audit-badges"><span class="${conflicts.size?'audit-warning':'audit-ok'}">${conflicts.size?`重複勤務 ${conflicts.size}枠`:'重複勤務なし'}</span>${disliked?`<span class="audit-warning">苦手な役職への割当 ${disliked}枠</span>`:''}</div></div>${conflicts.size?'<p>赤く表示されるドロップダウンは、他店舗・他の係を含め同じ時間に重複しています。</p>':''}<div class="hours-wrap"><table class="hours-table"><thead><tr><th>スタッフ</th>${dates.map((date,i)=>`<th>${esc(dayName(date,i))}</th>`).join('')}<th>合計</th></tr></thead><tbody>${rows}</tbody></table></div><p class="hours-note">勤務時間に昼食・休憩は含みません。「—」はその日に参加不可。</p>`;}
const roleNote=(role,count)=>`標準 ${count}人${tierRule[role]?`（${tierRule[role].tier}${tierRule[role].min}〜${tierRule[role].max}人）`:''}`;
const roleHead={'ドリッパー上級生':'ドリッパー<br>上級生','ドリッパー（下級生＋上級生）':'ドリッパー<br>下級生＋上級生'};
const roleHeadHtml=role=>roleHead[role]||esc(role);
const dripShort=t=>t?`${t[0]}${t.includes('ホット')?'H':'I'}`:'—';
let shortNames={};
function surname(name){const s=name.normalize('NFKC').trim(),parts=s.split(/\s+/);if(parts.length>1)return parts[0];const m=s.match(/^[一-鿿々ヶ]+/);if(m&&m[0].length<s.length)return m[0].slice(0,3);return s.slice(0,s[1]==='々'?3:2);}
function buildShortNames(){const groups={},flat=n=>n.normalize('NFKC').replace(/\s+/g,'');shortNames={};[...new Set(state.availability.map(a=>a.name))].forEach(n=>(groups[surname(n)]??=[]).push(n));for(const [base,list] of Object.entries(groups)){for(let k=0;k<=12;k++){const labels=list.map(n=>k?flat(n).slice(0,base.length+k):base);if(new Set(labels).size===labels.length||k===12){list.forEach((n,i)=>shortNames[n]=new Set(labels).size===labels.length?labels[i]:n);break;}}}}
const displayName=name=>state.fullNames?name:shortNames[name]||name;
function gridCellHtml(slot,audit,extra=''){const busy=(name,item)=>(audit.booked[`${name}|${item.date}`]||[]).some(b=>b.key!==item.key&&b.start<item.end&&item.start<b.end);const dayHours=(name,date)=>fmt(audit.hours[name]?.[date]||0);const items=Array.from({length:Math.max(0,Number(slot.count)||0)},(_,i)=>({...slot,occ:i,key:`${slot.id}-${i}`}));const f=fillOf(items);return `<td class="${storeClass(slot.store)} ${extra} cell-${f.cls||'none'}"><div class="grid-cell"><div class="cell-head"><button class="fill fill-${f.cls||'none'}" data-open-counts="${slot.id}" title="割当済み／必要人数（クリックで必要人数を設定）">${f.total?`${f.filled}/${f.total}`:'0人'}</button></div>${items.map(item=>{const chosen=state.assignments[item.key]||'';const choices=available(item);const kind=audit.conflicts.has(item.key)?'conflict':chosen&&dislikes(chosen,item.role)?'dislike':chosen?'filled':choices.length?'empty':'none';const label=chosen?`${wants(chosen,item.role)?'<i>★</i>':dislikes(chosen,item.role)?'<i>△</i>':''}${esc(displayName(chosen))}`:choices.length?'空き':'候補なし';const tip=chosen?`${chosen}（${dayHours(chosen,item.date)}）`:choices.length?`候補 ${choices.length}人：クリックして選択`:'条件に合うメンバーがいません';const pick=`<span class="pick pick-${kind}" title="${esc(tip)}"><span class="pick-label">${label}</span><select data-grid-assignment="${item.key}" aria-label="${esc(`${item.start} ${item.role}`)}"><option value="">未割当</option>${[...choices].sort((a,b)=>busy(a.name,item)-busy(b.name,item)).map(a=>`<option value="${esc(a.name)}" ${a.name===chosen?'selected':''}>${busy(a.name,item)&&a.name!==chosen?'⚠勤務中 ':''}${prefMark(a.name,item.role)}${esc(a.name)}（${dayHours(a.name,item.date)}）</option>`).join('')}</select></span>`;const t=slotChoices[item.role]?slotType(item):'';const type=slotChoices[item.role]?`<span class="pick type-pick ${t.includes('ホット')?'hot':t?'ice':''}" title="${esc(t||'種類未定')}"><span class="pick-label">${dripShort(t)}</span><select data-slot-type="${item.key}">${choiceOptions(item.role,t)}</select></span>`:'';const handle=chosen?`<span class="grab" draggable="true" data-drag-key="${item.key}" title="ドラッグ、またはクリックして移動先をクリック">⠿</span>`:'<span class="grab"></span>';return `<div class="slot" data-slot-key="${item.key}">${handle}${type}${pick}</div>`;}).join('')||'<span class="not-needed">不要</span>'}</div></td>`;}
function timelineHtml(dates,audit,storeFilter=''){const order=['準備',...storeNames],rows=[];for(const date of dates)for(const [store,roles] of Object.entries(rolesForDate(date)))for(const [role,count] of roles)if(!rows.some(r=>r.store===store&&r.role===role))rows.push({store,role,count});rows.sort((a,b)=>order.indexOf(a.store)-order.indexOf(b.store));if(storeFilter)rows.splice(0,rows.length,...rows.filter(r=>r.store===storeFilter));const days=dates.map((date,index)=>({date,index,hours:hoursForDate(date)}));return `<table class="shift-grid timeline"><thead><tr><th rowspan="2" class="corner">店舗・役職</th>${days.map(d=>`<th class="day-head day-start" colspan="${d.hours.length}">${esc(dayName(d.date,d.index))}　${esc(dayLabel(d.date))}</th>`).join('')}</tr><tr>${days.map(d=>d.hours.map((h,i)=>`<th class="hour-head ${i?'':'day-start'}" title="${h}–${plusHour(h)}">${h}</th>`).join('')).join('')}</tr></thead><tbody>${rows.map(({store,role,count})=>`<tr><th class="row-head ${storeClass(store)}" title="${esc(roleNote(role,count))}"><span>${esc(store)}</span><strong>${roleHeadHtml(role)}</strong></th>${days.map(d=>{const has=(rolesForDate(d.date)[store]||[]).some(([r])=>r===role);return d.hours.map((h,i)=>{const cls=i?'':'day-start';if(!has)return `<td class="na ${cls}"></td>`;return gridCellHtml(state.slots.find(s=>s.date===d.date&&s.store===store&&s.role===role&&s.start===h),audit,cls);}).join('');}).join('')}</tr>`).join('')}</tbody></table>`;}
function renderShiftGrid(){const empty=$('#shiftGridEmpty'),wrap=$('#shiftGridWrap');const dates=eventDates();if(!dates.length){$('#gridDates').innerHTML='';$('#gridStores').innerHTML='';empty.classList.remove('hidden');wrap.classList.add('hidden');renderAudit();return;}if(state.gridDate!=='all'&&!dates.includes(state.gridDate))state.gridDate=dates[0];ensureAllSlots();const items=flattened(),rate=list=>{const f=fillOf(list);return f.total?{badge:`${Math.round(f.filled/f.total*100)}%`,badgeClass:f.cls}:{};};$('#gridDates').innerHTML=segHtml([...dates.map((date,i)=>({value:date,label:dayName(date,i),sub:shortDay(date),...rate(items.filter(x=>x.date===date))})),...(dates.length>1?[{value:'all',label:`${dates.length}日分を一覧`,sub:'横長ビュー',...rate(items.filter(x=>dates.includes(x.date)))}]:[])],state.gridDate,'data-grid-date');const viewDates=state.gridDate==='all'?dates:[state.gridDate],order=['準備',...storeNames];const stores=[...new Set(viewDates.flatMap(d=>Object.keys(rolesForDate(d))))].sort((a,b)=>order.indexOf(a)-order.indexOf(b));const storeF=stores.includes(state.gridStore)?state.gridStore:'';const open=list=>`未割当 ${list.filter(x=>!state.assignments[x.key]).length}`,inView=items.filter(x=>viewDates.includes(x.date));$('#gridStores').innerHTML=stores.length>1?chipHtml([{value:'',label:'すべての店舗',badge:open(inView)},...stores.map(st=>({value:st,label:st,cls:storeClass(st),badge:open(inView.filter(x=>x.store===st))}))],storeF,'data-grid-store'):'';buildShortNames();$('#fullNameToggle').checked=!!state.fullNames;empty.classList.add('hidden');wrap.classList.remove('hidden');$('#gridLegend').textContent=state.gridDate==='all'?'行：店舗・役職 ／ 列：時間帯（斜線はその日にない役職）':'行：時間帯 ／ 列：役職';const audit=assignmentAudit();if(state.gridDate==='all'){wrap.innerHTML=timelineHtml(dates,audit,storeF);renderAudit(audit);stickGridHead();return;}const hours=hoursForDate(state.gridDate);const groups=Object.entries(rolesForDate(state.gridDate)).filter(([store])=>!storeF||store===storeF);const columns=groups.flatMap(([store,roles])=>roles.map(([role,count])=>({store,role,count})));wrap.innerHTML=`<table class="shift-grid day" style="min-width:${52+columns.length*96}px"><colgroup><col class="time-col">${columns.map(()=>'<col>').join('')}</colgroup><thead><tr><th rowspan="2">時間</th>${groups.map(([store,roles])=>`<th class="store-head ${storeClass(store)}" colspan="${roles.length}">${store}</th>`).join('')}</tr><tr>${columns.map(({store,role,count})=>`<th class="${storeClass(store)}" title="${esc(roleNote(role,count))}">${roleHeadHtml(role)}</th>`).join('')}</tr></thead><tbody>${hours.map(hour=>`<tr><th title="${hour}–${plusHour(hour)}">${hour}</th>${columns.map(({store,role})=>gridCellHtml(state.slots.find(s=>s.date===state.gridDate&&s.store===store&&s.role===role&&s.start===hour),audit)).join('')}</tr>`).join('')}</tbody></table>`;renderAudit(audit);stickGridHead();}
function render(){renderShiftGrid();renderAvailabilityBoard();renderMembers();renderRoleRules();updateStats();renderView();if(!$('#countDrawer').contains(document.activeElement))renderCountEditor();window.onStateChange?.();}
const dataViews=['availability','members','shift'];
function renderView(){const has=state.availability.length>0;if(!has&&dataViews.includes(state.view))state.view='import';document.body.dataset.view=state.view;document.querySelectorAll('main>[data-view]').forEach(el=>el.classList.toggle('hidden',el.dataset.view!==state.view));document.querySelectorAll('.tab').forEach(b=>{const t=b.dataset.tab,on=t===state.view;b.disabled=!has&&dataViews.includes(t);b.title=b.disabled?'CSVを読み込むと使えます':'';b.classList.toggle('active',on);b.setAttribute('aria-selected',String(on));});}
const showView=view=>{state.view=view;renderView();window.scrollTo(0,0);stickGridHead();};
function pruneAssignments(){const items=new Map(flattened().map(x=>[x.key,x]));let removed=0;for(const [key,name] of Object.entries(state.assignments)){if(!name)continue;const item=items.get(key);if(!item||!available(item).some(a=>a.name===name)){delete state.assignments[key];removed++;}}if(removed)showToast(`条件に合わなくなった ${removed} 枠の割当を外しました`);}
function addSlot(s){const defaultDate=[...new Set(state.availability.map(a=>a.date))].sort()[0]||new Date().toISOString().slice(0,10);const slot={date:defaultDate,store:'',role:'',start:'09:00',count:1,...s};slot.end=plusHour(slot.start);state.slots.push({...slot,id:uid()});render();}
const eventDates=()=>[...new Set(state.availability.map(a=>a.date))].sort().slice(0,3);
function ensureAllSlots(){eventDates().forEach(date=>ensureGridSlots(date,hoursForDate(date)));}
function autoAssign(){const workload={},booked={};state.assignments={};ensureAllSlots();for(const x of flattened()){const candidates=available(x).filter(a=>!(booked[a.name]||[]).some(b=>b.date===x.date&&x.start<b.end&&b.start<x.end));const rule=tierRule[x.role],prefer=rule&&siblingTiers(x).filter(t=>t===rule.tier).length<rule.min?rule.tier:'';const score=a=>(workload[a.name]||0)-(wants(a.name,x.role)?1:0);candidates.sort((a,b)=>(prefer?(tierOf(b.name)===prefer)-(tierOf(a.name)===prefer):0)||dislikes(a.name,x.role)-dislikes(b.name,x.role)||score(a)-score(b));if(candidates[0]){state.assignments[x.key]=candidates[0].name;workload[candidates[0].name]=(workload[candidates[0].name]||0)+1;(booked[candidates[0].name]??=[]).push(x);}}render();}
function download(name,text,type='text/csv;charset=utf-8'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();URL.revokeObjectURL(a.href);}
const printName=n=>`<span class="s">${esc(shortNames[n]||n)}</span><span class="f">${esc(n)}</span>`;
const printRole={'ドリッパー上級生':'ドリッパー上級生','ドリッパー（下級生＋上級生）':'ドリッパー（下級＋上級）','店舗準備（本店）':'店舗準備（本店）','店舗準備（2号店）':'店舗準備（2号店）','店舗準備（くれあ）':'店舗準備（くれあ）','実委からの受け取り':'受け取り'};
function printDayTable(date){const hours=hoursForDate(date),find=(store,role,h)=>state.slots.find(s=>s.date===date&&s.store===store&&s.role===role&&s.start===h);const groups=Object.entries(rolesForDate(date)),cols=[];for(const [store,roles] of groups)for(const [role] of roles){const max=Math.max(0,...hours.map(h=>Number(find(store,role,h)?.count)||0));for(let i=0;i<max;i++){const types=[...new Set(hours.map(h=>{const sl=find(store,role,h);return sl&&i<sl.count?slotType({role,key:`${sl.id}-${i}`,occ:i}):null;}).filter(t=>t!==null))];cols.push({store,role,i,label:`${printRole[role]||role}${max>1?i+1:''}`,type:types.length===1?types[0]:'',mixed:types.length>1,first:!cols.length||cols[cols.length-1].store!==store});}}if(!cols.length)return '<p class="meta">必要な枠がありません。</p>';const heads=groups.map(([store])=>[store,cols.filter(c=>c.store===store).length]).filter(([,n])=>n);const roleGroups=[];cols.forEach(c=>{const g=roleGroups[roleGroups.length-1];if(g&&g.store===c.store&&g.role===c.role)g.cols.push(c);else roleGroups.push({store:c.store,role:c.role,first:c.first,cols:[c]});});const typeTag=c=>c.type?`<small>${dripShort(c.type)}</small>`:'';return `<table class="grid ${cols.length>22?'dense':''}"><colgroup><col class="tc">${cols.map(()=>'<col>').join('')}</colgroup><thead><tr><th rowspan="3" class="time">Time</th>${heads.map(([store,n])=>`<th colspan="${n}" class="first">${esc(store)}</th>`).join('')}</tr><tr>${roleGroups.map(g=>`<th class="${g.first?'first':''}" ${g.cols.length>1?`colspan="${g.cols.length}"`:'rowspan="2"'}>${esc(printRole[g.role]||g.role)}${g.cols.length>1?'':typeTag(g.cols[0])}</th>`).join('')}</tr><tr>${roleGroups.filter(g=>g.cols.length>1).flatMap(g=>g.cols.map(c=>`<th class="num ${c.first?'first':''}">${c.i+1}${typeTag(c)}</th>`)).join('')}</tr></thead><tbody>${hours.map((h,r)=>`<tr class="${r%2?'':'band'}"><th class="time">${h}-${plusHour(h)}</th>${cols.map(c=>{const sl=find(c.store,c.role,h),cls=c.first?'first':'';if(!sl||c.i>=sl.count)return `<td class="na ${cls}"></td>`;const key=`${sl.id}-${c.i}`,n=state.assignments[key],t=c.mixed?slotType({role:c.role,key,occ:c.i}):'';return `<td class="${n?'':'open'} ${cls}">${n?printName(n):''}${t?`<small>${dripShort(t)}</small>`:''}</td>`;}).join('')}</tr>`).join('')}</tbody></table>`;}
function printPeople(date,audit){const names=[...new Set(state.availability.filter(a=>a.date===date).map(a=>a.name))].sort((a,b)=>a.localeCompare(b,'ja'));return `<div class="people-day">${names.map(n=>{const segs=personSegments(n,date);return `<div class="person ${segs.length?'':'none'}"><div class="ph"><b>${esc(n)}</b><span>${segs.length?fmt(audit.hours[n]?.[date]||0):'割当なし'}</span></div>${segs.map(sg=>`<div class="sg"><span>${sg.start}–${sg.end}</span>${esc(sg.label)}</div>`).join('')}</div>`;}).join('')}</div>`;}
