window.addEventListener('scroll',stickGridHead,{passive:true});$('#shiftGridWrap').addEventListener('scroll',stickGridHead,{passive:true});
$('.tabs').addEventListener('click',e=>{const b=e.target.closest('.tab');if(b&&!b.disabled)showView(b.dataset.tab);});
$('#importStatus').addEventListener('click',e=>{const b=e.target.closest('[data-goto]');if(b)showView(b.dataset.goto);});
$('#gridDates').addEventListener('click',e=>{const b=e.target.closest('[data-grid-date]');if(b){state.gridDate=b.dataset.gridDate;renderShiftGrid();}});
$('#gridStores').addEventListener('click',e=>{const b=e.target.closest('[data-grid-store]');if(b){state.gridStore=b.dataset.gridStore;renderShiftGrid();}});
$('#availDates').addEventListener('click',e=>{const b=e.target.closest('[data-avail-date]');if(b){state.availDate=b.dataset.availDate;renderAvailabilityBoard();}});
$('#memberSearch').addEventListener('input',e=>{state.memberQuery=e.target.value;renderMembers();});
$('#memberStoreFilter').addEventListener('click',e=>{const b=e.target.closest('[data-member-filter]');if(b){state.memberStore=b.dataset.memberFilter;renderMembers();}});
$('#shiftGridWrap').addEventListener('change',e=>{if(e.target.dataset.slotType!==undefined){const key=e.target.dataset.slotType;state.slotTypes[key]=e.target.value;const item=flattened().find(x=>x.key===key);if(item&&state.assignments[key]&&!available(item).some(a=>a.name===state.assignments[key]))state.assignments[key]='';render();return;}if(e.target.dataset.gridAssignment){state.assignments[e.target.dataset.gridAssignment]=e.target.value;render();}});
$('#memberEditor').addEventListener('change',e=>{if(e.target.dataset.member){state.memberStatuses[e.target.dataset.member]=e.target.value;pruneAssignments();render();}});
$('#memberEditor').addEventListener('change',e=>{if(e.target.dataset.memberStore){const name=e.target.dataset.memberStore;const stores=state.memberStores[name]||[];state.memberStores[name]=e.target.checked?[...new Set([...stores,e.target.value])]:stores.filter(store=>store!==e.target.value);pruneAssignments();render();}});
$('#memberEditor').addEventListener('change',e=>{if(e.target.dataset.memberWant!==undefined){state.memberWants[e.target.dataset.memberWant]=parseRoles(e.target.value).roles;render();}if(e.target.dataset.memberDislike!==undefined){state.memberDislikes[e.target.dataset.memberDislike]=parseRoles(e.target.value).roles;render();}if(e.target.dataset.memberCar){state.memberCars[e.target.dataset.memberCar]=e.target.checked;pruneAssignments();render();}if(e.target.dataset.memberDrip){const name=e.target.dataset.memberDrip;const drips=state.memberDrips[name]||[];state.memberDrips[name]=dripTypes.filter(t=>t===e.target.value?e.target.checked:drips.includes(t));pruneAssignments();render();}});
$('#roleRuleEditor').addEventListener('change',e=>{if(e.target.dataset.rule){state.roleRequirements[e.target.dataset.rule]=e.target.value;pruneAssignments();render();}});
$('#templateBtn').onclick=()=>download('survey_template.csv','\ufeff'+[['氏名','ステータス','所属店舗','対応できるドリップ','車の有無','やりたい役職','苦手な役職','日付','開始時刻','終了時刻'],['山田 太郎','2年目合格','本店','1杯ホット, 2杯ホット','あり','ドリッパー, レジ','マスター','2026-10-30','09:00','17:00'],['山田 太郎','2年目合格','本店','1杯ホット, 2杯ホット','あり','ドリッパー, レジ','マスター','2026-10-31','10:00','18:00'],['佐藤 花子','1年目合格','本店, くれあ','1杯アイス','なし','ホール','','2026-11-01','12:00','20:00']].map(csvLine).join('\n')+'\n');
$('#exportBtn').onclick=()=>{const rows=[['日付','店舗','ロール','種類・作業','開始時刻','終了時刻','担当者']];flattened().forEach(x=>rows.push([x.date,x.store,x.role,slotType(x),x.start,x.end,state.assignments[x.key]||'未割当']));download('shift.csv','\ufeff'+rows.map(r=>r.map(v=>`"${String(v).replaceAll('"','""')}"`).join(',')).join('\n'));};
state.roleRequirements[ruleKey('本店','マスター')]='上級生';state.roleRequirements[ruleKey('本店','ドリッパー上級生')]='上級生';state.roleRequirements[ruleKey('本店','ドリッパー（下級生＋上級生）')]='1年目合格';
const sampleNames=['佐藤あかり','鈴木凜太郎','高橋愛','田中はると','伊藤千尋','渡辺陽菜','山本蒼','中村結衣','小林蓮','加藤美咲','吉田颯太','山田葵','佐々木翔','山口彩花','松本悠斗','井上七海','木村健太','林優奈','斎藤大輔','清水真央','山崎拓海','森川琴音','池田直人','橋本莉子','阿部亮太','石川杏奈','前田航','藤田美月','岡田陸','長谷川紗良','村上悠真','近藤咲','石井蒼太','坂本美優','遠藤颯','青木彩','藤井大和','西村結菜','福田健','太田真奈','三浦陽介','岡本花','松田駿','中川葵','原田蓮','小野千夏','田村優斗','竹内美咲','金子翔太','和田結衣'];
const sampleDates=Object.keys(eventDays);
const sampleStatus=i=>i%10<3?'上級生':i%10<5?'2年目合格':i%10<8?'1年目合格':'未合格';
const sampleStores=i=>i<20?['本店']:i<30?['2号店']:i<40?['くれあ']:i<45?['本店','2号店']:['本店','くれあ'];
const sampleDrips=i=>sampleStores(i).includes('本店')?[dripTypes,['1杯ホット','1杯アイス'],['1杯ホット','2杯ホット'],['1杯アイス','2杯アイス','1杯ホット']][i%4]:[];
const sampleWants=i=>[['ドリッパー'],['レジ','ホール'],[],['提供'],['調理'],[]][i%6];
const sampleDislikes=i=>[[],['マスター'],[],['レジ'],[],[],['ホール']][i%7];
const csvLine=row=>row.map(v=>/[",\n]/.test(v)?`"${String(v).replaceAll('"','""')}"`:v).join(',');
function sampleCsv(){const hh=h=>`${String(h).padStart(2,'0')}:00`;const rows=[['氏名','ステータス','所属店舗','対応できるドリップ','車の有無','やりたい役職','苦手な役職','日付','開始時刻','終了時刻']];sampleNames.forEach((name,i)=>sampleDates.forEach((date,day)=>{const start=10+(i*3+day*2)%5,end=Math.min(20,start+5+(i+day)%5);rows.push([name,sampleStatus(i),sampleStores(i).join(', '),sampleDrips(i).join(', '),i%5===0?'あり':'なし',sampleWants(i).join(', '),sampleDislikes(i).join(', '),date,hh(start),hh(end)]);}));return '\ufeff'+rows.map(csvLine).join('\n');}
$('#sampleBtn').onclick=()=>{if(!importAllowed())return;state.slots=[];state.slotTypes={};state.slotCounts={};state.gridDate='';importCSV(sampleCsv(),'50名・3日間（10/30 前日準備、10/31・11/1 本番）のサンプルを読み込みました。ステータス・所属店舗・対応ドリップ・車の有無・役職の希望もCSVから反映しています。');};
$('#sampleDataBtn').onclick=()=>download('survey_sample_50members.csv',sampleCsv());
render();
